"""Small live client; displays recorded evidence without computing retrieval scores."""

import json


def render_live_dashboard(token: str, initial_state: dict | None = None) -> str:
    # Credentials arrive only in the private URL fragment, never in served HTML.
    payload = json.dumps({"state": initial_state}, ensure_ascii=False,
                         allow_nan=False).replace("&", "\\u0026").replace("<", "\\u003c").replace(">", "\\u003e")
    return _HTML.replace("__BOOTSTRAP__", payload)


